void TrafficLightSelectorNode::objectsCallback(
  const DetectedObjectsWithFeature::ConstSharedPtr & detected_traffic_light_msg,
  const TrafficLightRoiArray::ConstSharedPtr & rough_rois_msg,
  const TrafficLightRoiArray::ConstSharedPtr & expected_rois_msg,
  const sensor_msgs::msg::CameraInfo::ConstSharedPtr & camera_info_msg)
{
  stop_watch_ptr_->toc("processing_time", true);

  const auto image_width = camera_info_msg->width;
  const auto image_height = camera_info_msg->height;

  std::map<int64_t, RegionOfInterest> rough_rois_map;
  for (const auto & roi : rough_rois_msg->rois) {
    rough_rois_map[roi.traffic_light_id] = roi.roi;
  }

  std::vector<RegionOfInterest> detected_rois;
  for (const auto & detected_object : detected_traffic_light_msg->feature_objects) {
    detected_rois.push_back(detected_object.feature.roi);
  }

  double final_iou = 0.0;
  std::map<int64_t, RegionOfInterest> final_rois_map;
  for (const auto & expected_rois_msg_rois : expected_rois_msg->rois) {
    const auto traffic_light_id = expected_rois_msg_rois.traffic_light_id;
    const auto & rough_roi = rough_rois_map[traffic_light_id];
    const auto & expect_roi = expected_rois_msg_rois.roi;

    for (const auto & detected_roi : detected_rois) {
      if (!utils::isCenterInsideRoughRoi(detected_roi, rough_roi)) {
        continue;
      }

      // shift expect roi because the location of detected roi is better that it
      int32_t shift_x, shift_y;
      utils::computeCenterOffset(detected_roi, expect_roi, shift_x, shift_y);

      std::map<int64_t, RegionOfInterest> expect_rois_shifted_map;
      for (const auto & rois : expected_rois_msg->rois) {
        const auto expect_roi_shifted =
          utils::getShiftedRoi(rois.roi, image_width, image_height, shift_x, shift_y);
        expect_rois_shifted_map[rois.traffic_light_id] = expect_roi_shifted;
      }

      // check total IoU after all expect roi shift
      double total_max_iou = 0.0;
      std::map<int64_t, RegionOfInterest> total_max_iou_rois_map;
      evaluateWholeRois(
        detected_rois, expect_rois_shifted_map, total_max_iou, total_max_iou_rois_map);

      if (total_max_iou > final_iou) {
        final_iou = total_max_iou;
        final_rois_map = std::move(total_max_iou_rois_map);
      }
    }
  }

  // assign max iou roi to output
  TrafficLightRoiArray output;
  output.header = detected_traffic_light_msg->header;
  for (const auto & expected_rois_msg_rois : expected_rois_msg->rois) {
    const auto traffic_light_id = expected_rois_msg_rois.traffic_light_id;
    const auto traffic_light_type = expected_rois_msg_rois.traffic_light_type;
    TrafficLightRoi traffic_light_roi;

    if (final_rois_map.find(traffic_light_id) != final_rois_map.end()) {
      traffic_light_roi.traffic_light_id = traffic_light_id;
      traffic_light_roi.traffic_light_type = traffic_light_type;
      traffic_light_roi.roi = final_rois_map[traffic_light_id];
      output.rois.push_back(traffic_light_roi);
    } else {
      traffic_light_roi.traffic_light_id = traffic_light_id;
      traffic_light_roi.traffic_light_type = traffic_light_type;
      output.rois.push_back(traffic_light_roi);
    }
  }

  pub_traffic_light_rois_->publish(output);

  if (debug_publisher_) {
    const double processing_time_ms = stop_watch_ptr_->toc("processing_time", true);
    const double cyclic_time_ms = stop_watch_ptr_->toc("cyclic_time", true);
    const double pipeline_latency_ms =
      std::chrono::duration<double, std::milli>(
        std::chrono::nanoseconds((this->get_clock()->now() - output.header.stamp).nanoseconds()))
        .count();
    debug_publisher_->publish<autoware_internal_debug_msgs::msg::Float64Stamped>(
      "debug/cyclic_time_ms", cyclic_time_ms);
    debug_publisher_->publish<autoware_internal_debug_msgs::msg::Float64Stamped>(
      "debug/processing_time_ms", processing_time_ms);
    debug_publisher_->publish<autoware_internal_debug_msgs::msg::Float64Stamped>(
      "debug/pipeline_latency_ms", pipeline_latency_ms);
  }
}

bool isCenterInsideRoughRoi(
  const RegionOfInterest & detected_roi, const RegionOfInterest & rough_roi)
{
  const auto center_x = detected_roi.x_offset + detected_roi.width / 2;
  const auto center_y = detected_roi.y_offset + detected_roi.height / 2;

  return rough_roi.x_offset < center_x && center_x < rough_roi.x_offset + rough_roi.width &&
         rough_roi.y_offset < center_y && center_y < rough_roi.y_offset + rough_roi.height;
}

void computeCenterOffset(
  const RegionOfInterest & source, const RegionOfInterest & target, int32_t & shift_x,
  int32_t & shift_y)
{
  const auto source_roi_center_x = static_cast<int32_t>(source.x_offset + source.width / 2);
  const auto source_roi_center_y = static_cast<int32_t>(source.y_offset + source.height / 2);
  const auto target_roi_center_x = static_cast<int32_t>(target.x_offset + target.width / 2);
  const auto target_roi_center_y = static_cast<int32_t>(target.y_offset + target.height / 2);
  shift_x = source_roi_center_x - target_roi_center_x;
  shift_y = source_roi_center_y - target_roi_center_y;
}

RegionOfInterest getShiftedRoi(
  const RegionOfInterest & input_ROI, const uint32_t & image_width, const uint32_t & image_height,
  const int32_t & shift_x, const int32_t & shift_y)
{
  RegionOfInterest shifted_ROI = input_ROI;
  const auto x_offset = static_cast<int32_t>(input_ROI.x_offset) + shift_x;
  const auto y_offset = static_cast<int32_t>(input_ROI.y_offset) + shift_y;
  if (
    x_offset < 0 || y_offset < 0 || x_offset + input_ROI.width > image_width ||
    y_offset + input_ROI.height > image_height) {
    shifted_ROI.x_offset = 0;
    shifted_ROI.y_offset = 0;
    shifted_ROI.width = 0;
    shifted_ROI.height = 0;
  } else {
    shifted_ROI.x_offset = static_cast<uint32_t>(x_offset);
    shifted_ROI.y_offset = static_cast<uint32_t>(y_offset);
  }

  return shifted_ROI;
}

void TrafficLightSelectorNode::evaluateWholeRois(
  const std::vector<RegionOfInterest> & detected_rois,
  const std::map<int64_t, RegionOfInterest> & expect_rois_shifted_map, double & total_max_iou,
  std::map<int64_t, RegionOfInterest> & total_max_iou_rois_map)
{
  for (const auto & expect_roi_shifted : expect_rois_shifted_map) {
    double max_iou = 0.0;
    RegionOfInterest max_iou_roi;
    for (const auto & detected_roi : detected_rois) {
      const double iou = utils::getGenIoU(expect_roi_shifted.second, detected_roi);
      if (iou > max_iou) {
        max_iou = iou;
        max_iou_roi = detected_roi;
      }
    }
    total_max_iou += max_iou;
    total_max_iou_rois_map[expect_roi_shifted.first] = max_iou_roi;
  }
}

double getGenIoU(const RegionOfInterest & bbox1, const RegionOfInterest & bbox2)
{
  const auto intersection_x1 = std::max(bbox1.x_offset, bbox2.x_offset);
  const auto intersection_x2 = std::min(bbox1.x_offset + bbox1.width, bbox2.x_offset + bbox2.width);
  const auto intersection_y1 = std::max(bbox1.y_offset, bbox2.y_offset);
  const auto intersection_y2 =
    std::min(bbox1.y_offset + bbox1.height, bbox2.y_offset + bbox2.height);

  const auto intersection_area =
    std::max(static_cast<int32_t>(intersection_x2) - static_cast<int32_t>(intersection_x1), 0) *
    std::max(static_cast<int32_t>(intersection_y2) - static_cast<int32_t>(intersection_y1), 0);
  const auto union_area = static_cast<int32_t>(bbox1.width * bbox1.height) +
                          static_cast<int32_t>(bbox2.width * bbox2.height) - intersection_area;

  const auto convex_x1 = std::min(bbox1.x_offset, bbox2.x_offset);
  const auto convex_x2 = std::max(bbox1.x_offset + bbox1.width, bbox2.x_offset + bbox2.width);
  const auto convex_y1 = std::min(bbox1.y_offset, bbox2.y_offset);
  const auto convex_y2 = std::max(bbox1.y_offset + bbox1.height, bbox2.y_offset + bbox2.height);

  const auto convex_area = (static_cast<int32_t>(convex_x2) - static_cast<int32_t>(convex_x1)) *
                           (static_cast<int32_t>(convex_y2) - static_cast<int32_t>(convex_y1));
  const auto convex_without_1_and_2_area = convex_area - union_area;

  double iou;
  if (union_area == 0) {
    iou = 0.0;
  } else {
    iou = static_cast<double>(intersection_area) / static_cast<double>(union_area);
  }

  double giou;
  if (convex_area == 0) {
    giou = iou;
  } else {
    giou =
      iou - static_cast<double>(convex_without_1_and_2_area) / static_cast<double>(convex_area);
  }

  return giou;
}
